void GL::init()
{
  #ifdef USE_GLEW
	std::call_once(g_Init, [](){
		GLenum err = glewInit();
		if (GLEW_OK != err)
		{
			std::stringstream ss;
			ss << "unable to initialize the GLEW library: " << glewGetErrorString(err);
