69: 26. for (uint32_t j = 0; j < 128; j++) {
70: 27. float ypos = static_cast<float>(i) / 127.0f;
71: 28. float hue = ypos * 360.0f;
72: 29. float xpos = static_cast<float>(j) / 127.0f * 0.6f + 0.4f;
73: 30. // 饱和度和亮度设置为最大值以获取鲜艳的颜色
74: 31. nativeBuffer[i * 128 + j] = HSVtoRGB_U32(hue, xpos, 1.0f);
75: 32. }
76: 33. }
77: 34. OH_NativeBuffer_Unmap(m_nativeBuffer);
